// 題庫:依手冊(book)與主題(topic)標籤,供檢定引擎做弱點加權抽題
// 盡量以符號圖出題(img=題目附圖、optImgs=圖片選項),貼近真實看圖情境
export interface Question {
  id: string
  book: string // 手冊 slug:C2/A1/A2/C1/B1/A3/A4/D1
  topic: string // 主題標籤(弱點統計單位)
  q: string
  img?: string // 題目附圖(images/ 下的檔名)
  options: string[]
  optImgs?: string[] // 圖片選項(與 options 一一對應,options 作為圖片說明/正解顯示)
  a: number // 正解索引
  ex: string // 解析
}

